  static Future<void> seedInitialData(GeneratedDatabase db) async {
    final nowTimestamp = DateTime.now().toUtc().millisecondsSinceEpoch ~/ 1000;

    // 1. Seed BusinessSettings (exactly 1 record, idempotent)
    await db.customStatement(
      'INSERT OR IGNORE INTO business_settings '
      '(id, business_name, tax_enabled, tax_rate, created_at, updated_at) '
      'VALUES (?, ?, ?, ?, ?, ?);',
      [defaultBusinessSettingsId, '', 0, 0.0, nowTimestamp, nowTimestamp],
    );

    // 2. Seed Default ItemTypes (4 types, idempotent)
    for (final itemType in defaultItemTypes) {
      await db.customStatement(
        'INSERT OR IGNORE INTO item_types '
        '(id, name, is_active, created_at, updated_at) '
        'VALUES (?, ?, ?, ?, ?);',
        [itemType['id'], itemType['name'], 1, nowTimestamp, nowTimestamp],
      );
    }

    // 3. Seed Default ExpenseCategories (7 categories, idempotent)
    for (final category in defaultExpenseCategories) {
      await db.customStatement(
        'INSERT OR IGNORE INTO expense_categories '
        '(id, name, is_active, created_at, updated_at) '
        'VALUES (?, ?, ?, ?, ?);',
        [category['id'], category['name'], 1, nowTimestamp, nowTimestamp],
      );
    }

    // 4. Seed SyncState at the canonical remote baseline. This row is local
    // metadata and must not create an outbox operation.
    await db.customStatement(
      'INSERT OR IGNORE INTO sync_state '
      '(id, last_applied_sequence, updated_at) '
      'VALUES (?, ?, ?);',
      ['singleton', canonicalBaselineSequence, nowTimestamp],
    );

    // 5. Seed Services (5 canonical services, idempotent)
    for (final service in defaultServices) {
      await db.customStatement(
        'INSERT OR IGNORE INTO services '
        '(id, name, description, is_active, created_at, updated_at) '
        'VALUES (?, ?, ?, 1, ?, ?);',
        [
          service['id'],
          service['name'],
          service['description'],
          nowTimestamp,
          nowTimestamp,
        ],
      );
    }

    // 6. Seed Service Item Types (5 canonical pricing configurations, idempotent)
    for (final sit in defaultServiceItemTypes) {
      await db.customStatement(
        'INSERT OR IGNORE INTO service_item_types '
        '(id, service_id, item_type_id, pricing_type, price, created_at, updated_at) '
        'VALUES (?, ?, ?, ?, ?, ?, ?);',
        [
          sit['id'],
          sit['service_id'],
          sit['item_type_id'],
          sit['pricing_type'],
          sit['price'],
          nowTimestamp,
          nowTimestamp,
        ],
      );
    }

    // 7. Seed Carpet Sizes (3 canonical sizes, idempotent)
    for (final cs in defaultCarpetSizes) {
      await db.customStatement(
        'INSERT OR IGNORE INTO carpet_sizes '
        '(id, length, width, area, is_active, created_at, updated_at) '
        'VALUES (?, ?, ?, ?, 1, ?, ?);',
        [
          cs['id'],
          cs['length'],
          cs['width'],
          cs['area'],
          nowTimestamp,
          nowTimestamp,
        ],
      );
    }

    // 8. Seed Storage Locations (5 canonical locations, idempotent)
    for (final loc in defaultStorageLocations) {
      await db.customStatement(
        'INSERT OR IGNORE INTO storage_locations '
        '(id, name, is_active, created_at, updated_at) '
        'VALUES (?, ?, 1, ?, ?);',
        [loc['id'], loc['name'], nowTimestamp, nowTimestamp],
      );
    }

    // 9. Seed Storage Location Item Types (9 canonical junction rows, idempotent)
    for (final slit in defaultStorageLocationItemTypes) {
      await db.customStatement(
        'INSERT OR IGNORE INTO storage_location_item_types '
        '(id, storage_location_id, item_type_id, created_at) '
        'VALUES (?, ?, ?, ?);',
        [
          slit['id'],
          slit['storage_location_id'],
          slit['item_type_id'],
          nowTimestamp,
        ],
      );
    }

    // 10. Seed Item Definitions (10 canonical items, idempotent)
    for (final def in defaultItemDefinitions) {
      await db.customStatement(
        'INSERT OR IGNORE INTO item_definitions '
        '(id, item_type_id, name, is_active, created_at, updated_at) '
        'VALUES (?, ?, ?, 1, ?, ?);',
        [
          def['id'],
          def['item_type_id'],
          def['name'],
          nowTimestamp,
          nowTimestamp,
        ],
      );
    }

    // Explicit Invariant:
    // customers, orders, order_items, payments, expenses, storage_records,
    // and sync_operations are NEVER seeded. They remain strictly empty.
  }
}
